<?php require "config.php"; $error="";
if($_SERVER["REQUEST_METHOD"]==="POST"){ $s=$pdo->prepare("SELECT * FROM users WHERE email=?");$s->execute([trim($_POST["email"])]);$u=$s->fetch();if($u&&password_verify($_POST["password"],$u["password"])){$_SESSION["user_id"]=$u["id"];header("Location: dashboard.php");exit;}else $error="Invalid email or password.";} ?>
